// CONSOLIDAÇÃO — transforma os dados das 7 fontes em VETORES de risco
// Cada vetor: { chave, label, nivel, fonteCredito, sinceTxt, diasTxt,
//   descricao, impactoCruzado, camposupervisorKey, preponderante }
